1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math/big"
7		"sort"
8		"strings"
9	)
10	
11	// ---- 版税规则设置 ----
12	
13	// normalizeShares 校验并规范化规则份额：收款账户去重、比例范围与合计
14	// 校验（均为无状态的参数校验），并按收款账户排序，使同一规则与书写
15	// 顺序无关。返回规范化后的份额；参数不合法时返回 ErrInvalidArgument。
16	func normalizeShares(shares []RoyaltyShare) ([]royaltyShare, error) {
17		seen := make(map[string]bool, len(shares))
18		out := make([]royaltyShare, 0, len(shares))
19		var total int64
20		for _, sh := range shares {
21			if strings.TrimSpace(sh.AccountID) == "" {
22				return nil, fmt.Errorf("%w: 版税收款账户不能为空", ErrInvalidArgument)
23			}
24			if sh.Rate < 1 || sh.Rate > RoyaltyRateBase {
25				return nil, fmt.Errorf("%w: 账户 %s 的版税比例 %d 不在 1..%d 内",
26					ErrInvalidArgument, sh.AccountID, sh.Rate, RoyaltyRateBase)
27			}
28			if seen[sh.AccountID] {
29				return nil, fmt.Errorf("%w: 版税收款账户 %s 重复", ErrInvalidArgument, sh.AccountID)
30			}
31			seen[sh.AccountID] = true
32			total += sh.Rate
33			out = append(out, royaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
34		}
35		if total > RoyaltyRateBase {
36			return nil, fmt.Errorf("%w: 版税比例合计 %d 超过 %d", ErrInvalidArgument, total, RoyaltyRateBase)
37		}
38		sort.Slice(out, func(i, j int) bool { return out[i].AccountID < out[j].AccountID })
39		return out, nil
40	}
41	
42	func (req SetRoyaltyRequest) validatePresent() error {
43		missing := []string{}
44		if strings.TrimSpace(req.Operator) == "" {
45			missing = append(missing, "operator")
46		}
47		if strings.TrimSpace(req.Reason) == "" {
48			missing = append(missing, "reason")
49		}
50		if strings.TrimSpace(req.RequestID) == "" {
51			missing = append(missing, "request_id")
52		}
53		if strings.TrimSpace(req.SeriesID) == "" {
54			missing = append(missing, "series_id")
55		}
56		if len(missing) > 0 {
57			return fmt.Errorf("%w: 设置版税规则请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
58		}
59		return nil
60	}
61	
62	func setRoyaltyParamsSig(req SetRoyaltyRequest, shares []royaltyShare) string {
63		b, _ := json.Marshal(struct {
64			Kind     string         `json:"kind"`
65			SeriesID string         `json:"series_id"`
66			Shares   []royaltyShare `json:"shares"`
67			Reason   string         `json:"reason"`
68		}{"royalty_set", req.SeriesID, shares, req.Reason})
69		return string(b)
70	}
71	
72	// SetRoyalty 设置或清空系列的版税规则，并记录本次变更的操作者、原因、
73	// 请求号与前后内容。只有系列创建账户（且可用）可以设置；每个收款账户
74	// 只能出现一次，比例是 1..10000 的整数（万分之一），合计不超过 10000；
75	// Shares 为空表示清空规则、不收版税。首次成功发行后规则固定（未设置
76	// 即固定为无版税），封存后同样拒绝设置。
77	//
78	// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
79	// 重提返回首次结果，参数不同返回 ErrRequestConflict；参数错误与引用
80	// 不存在不占用请求号。
81	func (r *Registry) SetRoyalty(req SetRoyaltyRequest) (SetRoyaltyResult, error) {
82		if err := req.validatePresent(); err != nil {
83			return SetRoyaltyResult{}, err
84		}
85		// 份额的形状校验（重复账户、比例范围、合计）不依赖状态，在取锁前
86		// 完成；不合法时原规则不变，也不占用请求号。
87		shares, err := normalizeShares(req.Shares)
88		if err != nil {
89			return SetRoyaltyResult{SeriesID: req.SeriesID, Err: err}, err
90		}
91		r.mu.Lock()
92		defer r.mu.Unlock()
93		if err := r.checkOpen(); err != nil {
94			return SetRoyaltyResult{}, err
95		}
96	
97		key := requestKey(req.Operator, req.RequestID)
98		sig := setRoyaltyParamsSig(req, shares)
99		if prev, ok := r.state.Requests[key]; ok {
100			return r.replaySetRoyalty(prev, sig)
101		}
102	
103		if bizErr := r.checkSetRoyalty(req, shares); bizErr != nil {
104			if !isValidationErr(bizErr) {
105				// 状态类业务拒绝（停用、无权、封存、已固定等）占用请求号并
106				// 落盘；参数错误与引用不存在不占用。
107				r.state.Requests[key] = request{
108					Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
109					Params: sig, Rejected: true, Reason: errCode(bizErr),
110					SeriesID: req.SeriesID,
111				}
112				_ = r.commit()
113			}
114			return SetRoyaltyResult{SeriesID: req.SeriesID, Err: bizErr}, bizErr
115		}
116	
117		s := r.state.Series[req.SeriesID]
118		before := append([]royaltyShare(nil), s.Royalty...)
119		s.Royalty = shares
120		r.state.Series[req.SeriesID] = s
121		seq := r.state.NextRoyaltySeq + 1
122		r.state.NextRoyaltySeq = seq
123		r.state.RoyaltyEvents = append(r.state.RoyaltyEvents, royaltyEvent{
124			Seq: seq, SeriesID: req.SeriesID, Operator: req.Operator,
125			Reason: req.Reason, RequestID: req.RequestID,
126			Before: before, After: append([]royaltyShare(nil), shares...),
127			OccurredAt: r.now(),
128		})
129		r.state.Requests[key] = request{
130			Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
131			Params: sig, SeriesID: req.SeriesID, Shares: shares,
132		}
133		if err := r.commit(); err != nil {
134			return SetRoyaltyResult{}, err
135		}
136		return SetRoyaltyResult{SeriesID: req.SeriesID, Shares: publicShares(shares)}, nil
137	}
138	
139	func (r *Registry) checkSetRoyalty(req SetRoyaltyRequest, shares []royaltyShare) error {
140		op, ok := r.state.Accounts[req.Operator]
141		if !ok {
142			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
143		}
144		if !op.Active {
145			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
146		}
147		s, ok := r.state.Series[req.SeriesID]
148		if !ok {
149			return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
150		}
151		if s.CreatorID != req.Operator {
152			return fmt.Errorf("%w: 只有创建账户 %s 可以设置系列 %s 的版税规则",
153				ErrForbidden, s.CreatorID, req.SeriesID)
154		}
155		if s.Sealed {
156			return fmt.Errorf("%w: 系列 %s 已封存，不能设置版税规则", ErrSeriesSealed, req.SeriesID)
157		}
158		// 首次成功发行后规则固定：系列中已存在藏品即视为已固定。
159		for _, it := range r.state.Items {
160			if it.SeriesID == req.SeriesID {
161				return fmt.Errorf("%w: 系列 %s 已发行藏品，版税规则不能再设置",
162					ErrRoyaltyFrozen, req.SeriesID)
163			}
164		}
165		for _, sh := range shares {
166			payee, ok := r.state.Accounts[sh.AccountID]
167			if !ok {
168				return fmt.Errorf("%w: 版税收款账户 %s", ErrNotFound, sh.AccountID)
169			}
170			if !payee.Active {
171				return fmt.Errorf("%w: 版税收款账户 %s", ErrAccountInactive, sh.AccountID)
172			}
173		}
174		return nil
175	}
176	
177	func (r *Registry) replaySetRoyalty(prev request, sig string) (SetRoyaltyResult, error) {
178		if prev.Kind != "royalty_set" || prev.Params != sig {
179			return SetRoyaltyResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
180				ErrRequestConflict, prev.Operator, prev.RequestID)
181		}
182		res := SetRoyaltyResult{SeriesID: prev.SeriesID, Shares: publicShares(prev.Shares), Replayed: true}
183		if prev.Rejected {
184			res.Err = codeErr(prev.Reason)
185			res.Shares = nil
186			return res, res.Err
187		}
188		return res, nil
189	}
190	
191	// ---- 版税计算 ----
192	
193	// royaltyAmount 计算单个收款账户的应付金额：价款乘比例除以 10000 向下
194	// 取整。价款与比例的乘积可能超出 int64，用 big.Int 保证整个价款范围
195	// 内结果准确；结果不超过价款本身，可安全转回 int64。
196	func royaltyAmount(price, rate int64) int64 {
197		amt := big.NewInt(price)
198		amt.Mul(amt, big.NewInt(rate))
199		amt.Div(amt, big.NewInt(RoyaltyRateBase))
200		return amt.Int64()
201	}
202	
203	// newRoyaltyRec 按规则快照计算一笔转让的全部应付明细与剩余收入。
204	// 零金额的应付也保留明细；余款归转让前持有人（ownerID）。
205	func newRoyaltyRec(txSeq int64, itemID, seriesID string, price int64, shares []royaltyShare, ownerID string) royaltyRec {
206		rec := royaltyRec{
207			TxSeq: txSeq, ItemID: itemID, SeriesID: seriesID,
208			Price: price, OwnerID: ownerID,
209		}
210		var total int64
211		for _, sh := range shares {
212			amt := royaltyAmount(price, sh.Rate)
213			rec.Payees = append(rec.Payees, payableLine{
214				AccountID: sh.AccountID, Rate: sh.Rate, Amount: amt,
215			})
216			total += amt
217		}
218		// 比例合计不超过 10000，应付合计不超过价款，余款非负且不溢出。
219		rec.Remainder = price - total
220		return rec
221	}
222	
223	func publicShares(shares []royaltyShare) []RoyaltyShare {
224		out := make([]RoyaltyShare, 0, len(shares))
225		for _, sh := range shares {
226			out = append(out, RoyaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
227		}
228		return out
229	}
230	
231	func publicPayables(payees []payableLine) []RoyaltyPayable {
232		out := make([]RoyaltyPayable, 0, len(payees))
233		for _, p := range payees {
234			out = append(out, RoyaltyPayable{AccountID: p.AccountID, Rate: p.Rate, Amount: p.Amount})
235		}
236		return out
237	}
238	
239	// royaltyOfTx 返回某笔成功转让落盘的价款、应付明细与余款；旧登记册中
240	// 的转让没有记录，按价款 0、无明细处理。调用时需持有锁。
241	func (r *Registry) royaltyOfTx(txSeq int64) (int64, []RoyaltyPayable, int64) {
242		rec, ok := r.state.Royalties[txSeq]
243		if !ok {
244			return 0, nil, 0
245		}
246		return rec.Price, publicPayables(rec.Payees), rec.Remainder
247	}
248	
249	// ---- 版税查询 ----
250	
251	// GetSeriesRoyalty 查询系列当前的版税规则（按收款账户排序）；未设置或
252	// 已清空时返回空列表。系列不存在时返回包裹 ErrNotFound 的错误。
253	func (r *Registry) GetSeriesRoyalty(seriesID string) ([]RoyaltyShare, error) {
254		r.mu.Lock()
255		defer r.mu.Unlock()
256		if err := r.checkOpen(); err != nil {
257			return nil, err
258		}
259		s, ok := r.state.Series[seriesID]
260		if !ok {
261			return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
262		}
263		return publicShares(s.Royalty), nil
264	}
265	
266	// RoyaltyHistory 查询系列版税规则的历次变更，按发生先后排列；每条
267	// 记录包含操作者、原因、请求号与前后内容。系列不存在时返回包裹
268	// ErrNotFound 的错误。
269	func (r *Registry) RoyaltyHistory(seriesID string) ([]RoyaltyEvent, error) {
270		r.mu.Lock()
271		defer r.mu.Unlock()
272		if err := r.checkOpen(); err != nil {
273			return nil, err
274		}
275		if _, ok := r.state.Series[seriesID]; !ok {
276			return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
277		}
278		out := make([]RoyaltyEvent, 0)
279		for _, e := range r.state.RoyaltyEvents {
280			if e.SeriesID != seriesID {
281				continue
282			}
283			out = append(out, RoyaltyEvent{
284				Seq: e.Seq, SeriesID: e.SeriesID, Operator: e.Operator,
285				Reason: e.Reason, RequestID: e.RequestID,
286				Before: publicShares(e.Before), After: publicShares(e.After),
287				OccurredAt: e.OccurredAt,
288			})
289		}
290		return out, nil
291	}
292	
293	// TransferRoyalty 按转让历史序号查询一笔成功转让的版税计算依据与全部
294	// 金额：成交价款、各收款账户应付明细（含零金额）与归转让前持有人的
295	// 剩余收入。序号不是成功的转让记录（不存在或为发行记录）时返回包裹
296	// ErrNotFound 的错误；旧登记册中的转让按价款 0、无应付明细返回。
297	func (r *Registry) TransferRoyalty(txSeq int64) (TransferRoyalty, error) {
298		r.mu.Lock()
299		defer r.mu.Unlock()
300		if err := r.checkOpen(); err != nil {
301			return TransferRoyalty{}, err
302		}
303		if txSeq <= 0 {
304			return TransferRoyalty{}, fmt.Errorf("%w: 转让序号 %d 不合法", ErrInvalidArgument, txSeq)
305		}
306		var entry *historyEntry
307		for i := range r.state.History {
308			if r.state.History[i].Seq == txSeq {
309				entry = &r.state.History[i]
310				break
311			}
312		}
313		if entry == nil || entry.Kind != "transfer" {
314			return TransferRoyalty{}, fmt.Errorf("%w: 转让记录 %d", ErrNotFound, txSeq)
315		}
316		out := TransferRoyalty{
317			TxSeq: txSeq, ItemID: entry.ItemID, OwnerID: entry.FromID,
318			Payables: make([]RoyaltyPayable, 0),
319		}
320		if rec, ok := r.state.Royalties[txSeq]; ok {
321			out.Price = rec.Price
322			out.Payables = publicPayables(rec.Payees)
323			out.Remainder = rec.Remainder
324			out.OwnerID = rec.OwnerID
325		}
326		return out, nil
327	}
328	
329	// PayablesOf 查询某账户作为版税收款账户的全部应付明细，按转让序号
330	// 排列；没有明细时返回空列表。账户不存在时返回包裹 ErrNotFound 的
331	// 错误；停用账户的既有应付记录仍可查询。
332	func (r *Registry) PayablesOf(accountID string) ([]PayableEntry, error) {
333		r.mu.Lock()
334		defer r.mu.Unlock()
335		if err := r.checkOpen(); err != nil {
336			return nil, err
337		}
338		if _, ok := r.state.Accounts[accountID]; !ok {
339			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
340		}
341		out := make([]PayableEntry, 0)
342		for _, rec := range r.state.Royalties {
343			for _, p := range rec.Payees {
344				if p.AccountID != accountID {
345					continue
346				}
347				out = append(out, PayableEntry{
348					TxSeq: rec.TxSeq, ItemID: rec.ItemID, Price: rec.Price,
349					Rate: p.Rate, Amount: p.Amount,
350				})
351			}
352		}
353		sort.Slice(out, func(i, j int) bool { return out[i].TxSeq < out[j].TxSeq })
354		return out, nil
355	}
