package registry

import (
	"encoding/json"
	"fmt"
	"math/big"
	"sort"
	"strings"
)

// ---- 版税规则设置 ----

// normalizeShares 校验并规范化规则份额：收款账户去重、比例范围与合计
// 校验（均为无状态的参数校验），并按收款账户排序，使同一规则与书写
// 顺序无关。返回规范化后的份额；参数不合法时返回 ErrInvalidArgument。
func normalizeShares(shares []RoyaltyShare) ([]royaltyShare, error) {
	seen := make(map[string]bool, len(shares))
	out := make([]royaltyShare, 0, len(shares))
	var total int64
	for _, sh := range shares {
		if strings.TrimSpace(sh.AccountID) == "" {
			return nil, fmt.Errorf("%w: 版税收款账户不能为空", ErrInvalidArgument)
		}
		if sh.Rate < 1 || sh.Rate > RoyaltyRateBase {
			return nil, fmt.Errorf("%w: 账户 %s 的版税比例 %d 不在 1..%d 内",
				ErrInvalidArgument, sh.AccountID, sh.Rate, RoyaltyRateBase)
		}
		if seen[sh.AccountID] {
			return nil, fmt.Errorf("%w: 版税收款账户 %s 重复", ErrInvalidArgument, sh.AccountID)
		}
		seen[sh.AccountID] = true
		total += sh.Rate
		out = append(out, royaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
	}
	if total > RoyaltyRateBase {
		return nil, fmt.Errorf("%w: 版税比例合计 %d 超过 %d", ErrInvalidArgument, total, RoyaltyRateBase)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].AccountID < out[j].AccountID })
	return out, nil
}

func (req SetRoyaltyRequest) validatePresent() error {
	missing := []string{}
	if strings.TrimSpace(req.Operator) == "" {
		missing = append(missing, "operator")
	}
	if strings.TrimSpace(req.Reason) == "" {
		missing = append(missing, "reason")
	}
	if strings.TrimSpace(req.RequestID) == "" {
		missing = append(missing, "request_id")
	}
	if strings.TrimSpace(req.SeriesID) == "" {
		missing = append(missing, "series_id")
	}
	if len(missing) > 0 {
		return fmt.Errorf("%w: 设置版税规则请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
	}
	return nil
}

func setRoyaltyParamsSig(req SetRoyaltyRequest, shares []royaltyShare) string {
	b, _ := json.Marshal(struct {
		Kind     string         `json:"kind"`
		SeriesID string         `json:"series_id"`
		Shares   []royaltyShare `json:"shares"`
		Reason   string         `json:"reason"`
	}{"royalty_set", req.SeriesID, shares, req.Reason})
	return string(b)
}

// SetRoyalty 设置或清空系列的版税规则，并记录本次变更的操作者、原因、
// 请求号与前后内容。只有系列创建账户（且可用）可以设置；每个收款账户
// 只能出现一次，比例是 1..10000 的整数（万分之一），合计不超过 10000；
// Shares 为空表示清空规则、不收版税。首次成功发行后规则固定（未设置
// 即固定为无版税），封存后同样拒绝设置。
//
// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
// 重提返回首次结果，参数不同返回 ErrRequestConflict；参数错误与引用
// 不存在不占用请求号。
func (r *Registry) SetRoyalty(req SetRoyaltyRequest) (SetRoyaltyResult, error) {
	if err := req.validatePresent(); err != nil {
		return SetRoyaltyResult{}, err
	}
	// 份额的形状校验（重复账户、比例范围、合计）不依赖状态，在取锁前
	// 完成；不合法时原规则不变，也不占用请求号。
	shares, err := normalizeShares(req.Shares)
	if err != nil {
		return SetRoyaltyResult{SeriesID: req.SeriesID, Err: err}, err
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return SetRoyaltyResult{}, err
	}

	key := requestKey(req.Operator, req.RequestID)
	sig := setRoyaltyParamsSig(req, shares)
	if prev, ok := r.state.Requests[key]; ok {
		return r.replaySetRoyalty(prev, sig)
	}

	if bizErr := r.checkSetRoyalty(req, shares); bizErr != nil {
		if !isValidationErr(bizErr) {
			// 状态类业务拒绝（停用、无权、封存、已固定等）占用请求号并
			// 落盘；参数错误与引用不存在不占用。
			r.state.Requests[key] = request{
				Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
				Params: sig, Rejected: true, Reason: errCode(bizErr),
				SeriesID: req.SeriesID,
			}
			_ = r.commit()
		}
		return SetRoyaltyResult{SeriesID: req.SeriesID, Err: bizErr}, bizErr
	}

	s := r.state.Series[req.SeriesID]
	before := append([]royaltyShare(nil), s.Royalty...)
	s.Royalty = shares
	r.state.Series[req.SeriesID] = s
	seq := r.state.NextRoyaltySeq + 1
	r.state.NextRoyaltySeq = seq
	r.state.RoyaltyEvents = append(r.state.RoyaltyEvents, royaltyEvent{
		Seq: seq, SeriesID: req.SeriesID, Operator: req.Operator,
		Reason: req.Reason, RequestID: req.RequestID,
		Before: before, After: append([]royaltyShare(nil), shares...),
		OccurredAt: r.now(),
	})
	r.state.Requests[key] = request{
		Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
		Params: sig, SeriesID: req.SeriesID, Shares: shares,
	}
	if err := r.commit(); err != nil {
		return SetRoyaltyResult{}, err
	}
	return SetRoyaltyResult{SeriesID: req.SeriesID, Shares: publicShares(shares)}, nil
}

func (r *Registry) checkSetRoyalty(req SetRoyaltyRequest, shares []royaltyShare) error {
	op, ok := r.state.Accounts[req.Operator]
	if !ok {
		return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
	}
	if !op.Active {
		return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
	}
	s, ok := r.state.Series[req.SeriesID]
	if !ok {
		return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
	}
	if s.CreatorID != req.Operator {
		return fmt.Errorf("%w: 只有创建账户 %s 可以设置系列 %s 的版税规则",
			ErrForbidden, s.CreatorID, req.SeriesID)
	}
	if s.Sealed {
		return fmt.Errorf("%w: 系列 %s 已封存，不能设置版税规则", ErrSeriesSealed, req.SeriesID)
	}
	// 首次成功发行后规则固定：系列中已存在藏品即视为已固定。
	for _, it := range r.state.Items {
		if it.SeriesID == req.SeriesID {
			return fmt.Errorf("%w: 系列 %s 已发行藏品，版税规则不能再设置",
				ErrRoyaltyFrozen, req.SeriesID)
		}
	}
	for _, sh := range shares {
		payee, ok := r.state.Accounts[sh.AccountID]
		if !ok {
			return fmt.Errorf("%w: 版税收款账户 %s", ErrNotFound, sh.AccountID)
		}
		if !payee.Active {
			return fmt.Errorf("%w: 版税收款账户 %s", ErrAccountInactive, sh.AccountID)
		}
	}
	return nil
}

func (r *Registry) replaySetRoyalty(prev request, sig string) (SetRoyaltyResult, error) {
	if prev.Kind != "royalty_set" || prev.Params != sig {
		return SetRoyaltyResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
			ErrRequestConflict, prev.Operator, prev.RequestID)
	}
	res := SetRoyaltyResult{SeriesID: prev.SeriesID, Shares: publicShares(prev.Shares), Replayed: true}
	if prev.Rejected {
		res.Err = codeErr(prev.Reason)
		res.Shares = nil
		return res, res.Err
	}
	return res, nil
}

// ---- 版税计算 ----

// royaltyAmount 计算单个收款账户的应付金额：价款乘比例除以 10000 向下
// 取整。价款与比例的乘积可能超出 int64，用 big.Int 保证整个价款范围
// 内结果准确；结果不超过价款本身，可安全转回 int64。
func royaltyAmount(price, rate int64) int64 {
	amt := big.NewInt(price)
	amt.Mul(amt, big.NewInt(rate))
	amt.Div(amt, big.NewInt(RoyaltyRateBase))
	return amt.Int64()
}

// newRoyaltyRec 按规则快照计算一笔转让的全部应付明细与剩余收入。
// 零金额的应付也保留明细；余款归转让前持有人（ownerID）。
func newRoyaltyRec(txSeq int64, itemID, seriesID string, price int64, shares []royaltyShare, ownerID string) royaltyRec {
	rec := royaltyRec{
		TxSeq: txSeq, ItemID: itemID, SeriesID: seriesID,
		Price: price, OwnerID: ownerID,
	}
	var total int64
	for _, sh := range shares {
		amt := royaltyAmount(price, sh.Rate)
		rec.Payees = append(rec.Payees, payableLine{
			AccountID: sh.AccountID, Rate: sh.Rate, Amount: amt,
		})
		total += amt
	}
	// 比例合计不超过 10000，应付合计不超过价款，余款非负且不溢出。
	rec.Remainder = price - total
	return rec
}

func publicShares(shares []royaltyShare) []RoyaltyShare {
	out := make([]RoyaltyShare, 0, len(shares))
	for _, sh := range shares {
		out = append(out, RoyaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
	}
	return out
}

func publicPayables(payees []payableLine) []RoyaltyPayable {
	out := make([]RoyaltyPayable, 0, len(payees))
	for _, p := range payees {
		out = append(out, RoyaltyPayable{AccountID: p.AccountID, Rate: p.Rate, Amount: p.Amount})
	}
	return out
}

// royaltyOfTx 返回某笔成功转让落盘的价款、应付明细与余款；旧登记册中
// 的转让没有记录，按价款 0、无明细处理。调用时需持有锁。
func (r *Registry) royaltyOfTx(txSeq int64) (int64, []RoyaltyPayable, int64) {
	rec, ok := r.state.Royalties[txSeq]
	if !ok {
		return 0, nil, 0
	}
	return rec.Price, publicPayables(rec.Payees), rec.Remainder
}

// ---- 版税查询 ----

// GetSeriesRoyalty 查询系列当前的版税规则（按收款账户排序）；未设置或
// 已清空时返回空列表。系列不存在时返回包裹 ErrNotFound 的错误。
func (r *Registry) GetSeriesRoyalty(seriesID string) ([]RoyaltyShare, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	s, ok := r.state.Series[seriesID]
	if !ok {
		return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
	}
	return publicShares(s.Royalty), nil
}

// RoyaltyHistory 查询系列版税规则的历次变更，按发生先后排列；每条
// 记录包含操作者、原因、请求号与前后内容。系列不存在时返回包裹
// ErrNotFound 的错误。
func (r *Registry) RoyaltyHistory(seriesID string) ([]RoyaltyEvent, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	if _, ok := r.state.Series[seriesID]; !ok {
		return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
	}
	out := make([]RoyaltyEvent, 0)
	for _, e := range r.state.RoyaltyEvents {
		if e.SeriesID != seriesID {
			continue
		}
		out = append(out, RoyaltyEvent{
			Seq: e.Seq, SeriesID: e.SeriesID, Operator: e.Operator,
			Reason: e.Reason, RequestID: e.RequestID,
			Before: publicShares(e.Before), After: publicShares(e.After),
			OccurredAt: e.OccurredAt,
		})
	}
	return out, nil
}

// TransferRoyalty 按转让历史序号查询一笔成功转让的版税计算依据与全部
// 金额：成交价款、各收款账户应付明细（含零金额）与归转让前持有人的
// 剩余收入。序号不是成功的转让记录（不存在或为发行记录）时返回包裹
// ErrNotFound 的错误；旧登记册中的转让按价款 0、无应付明细返回。
func (r *Registry) TransferRoyalty(txSeq int64) (TransferRoyalty, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return TransferRoyalty{}, err
	}
	if txSeq <= 0 {
		return TransferRoyalty{}, fmt.Errorf("%w: 转让序号 %d 不合法", ErrInvalidArgument, txSeq)
	}
	var entry *historyEntry
	for i := range r.state.History {
		if r.state.History[i].Seq == txSeq {
			entry = &r.state.History[i]
			break
		}
	}
	if entry == nil || entry.Kind != "transfer" {
		return TransferRoyalty{}, fmt.Errorf("%w: 转让记录 %d", ErrNotFound, txSeq)
	}
	out := TransferRoyalty{
		TxSeq: txSeq, ItemID: entry.ItemID, OwnerID: entry.FromID,
		Payables: make([]RoyaltyPayable, 0),
	}
	if rec, ok := r.state.Royalties[txSeq]; ok {
		out.Price = rec.Price
		out.Payables = publicPayables(rec.Payees)
		out.Remainder = rec.Remainder
		out.OwnerID = rec.OwnerID
	}
	return out, nil
}

// PayablesOf 查询某账户作为版税收款账户的全部应付明细，按转让序号
// 排列；没有明细时返回空列表。账户不存在时返回包裹 ErrNotFound 的
// 错误；停用账户的既有应付记录仍可查询。
func (r *Registry) PayablesOf(accountID string) ([]PayableEntry, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return nil, err
	}
	if _, ok := r.state.Accounts[accountID]; !ok {
		return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
	}
	out := make([]PayableEntry, 0)
	for _, rec := range r.state.Royalties {
		for _, p := range rec.Payees {
			if p.AccountID != accountID {
				continue
			}
			out = append(out, PayableEntry{
				TxSeq: rec.TxSeq, ItemID: rec.ItemID, Price: rec.Price,
				Rate: p.Rate, Amount: p.Amount,
			})
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].TxSeq < out[j].TxSeq })
	return out, nil
}

package registry

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"syscall"
	"time"
)

// stateVersion 是快照格式的版本标记，未来不兼容变更时可据此识别。
const stateVersion = 1

const (
	dirMode  = 0o755
	fileMode = 0o644
)

// snapshot 是登记册的全量落盘结构。账户、系列、藏品、持有、历史、
// 授权、授权变更记录与请求结果都在同一个快照中，一次操作一次原子
// 替换，保证"藏品已换人就一定有对应历史"。
type snapshot struct {
	Version  int                 `json:"version"`
	Accounts map[string]account  `json:"accounts"`
	Series   map[string]series   `json:"series"`
	Items    map[string]item     `json:"items"`
	Holdings map[string]holding  `json:"holdings"`
	History  []historyEntry      `json:"history"`
	Requests map[string]request  `json:"requests"`
	Authzs   map[string]authzRec `json:"authzs,omitempty"`
	// AuthEvents 是按藏品记录的授权变更（创建/撤销/使用），在藏品
	// 历史之外单独编号，不影响既有历史序号。
	AuthEvents  []authzEvent `json:"auth_events,omitempty"`
	NextSeq     int64        `json:"next_seq"`
	NextAuthSeq int64        `json:"next_auth_seq,omitempty"`
	// Royalties 以转让历史序号为键，记录每笔成功转让的版税计算依据与
	// 应付明细；旧登记册中的转让没有记录，查询时按价款 0 处理，不补造。
	Royalties map[int64]royaltyRec `json:"royalties,omitempty"`
	// RoyaltyEvents 是版税规则变更记录，单独编号。
	RoyaltyEvents  []royaltyEvent `json:"royalty_events,omitempty"`
	NextRoyaltySeq int64          `json:"next_royalty_seq,omitempty"`
	// Intents 是拆分意向表；只记录未来拆分的约定，不影响持有与版税。
	Intents map[string]intentRec `json:"intents,omitempty"`
	// IntentEvents 是拆分意向变更记录（创建/首次答复/撤回），单独编号。
	IntentEvents  []intentEvent `json:"intent_events,omitempty"`
	NextIntentSeq int64         `json:"next_intent_seq,omitempty"`
}

type account struct {
	ID       string `json:"id"`
	Metadata string `json:"metadata"`
	Active   bool   `json:"active"`
}

type series struct {
	ID        string `json:"id"`
	CreatorID string `json:"creator_id"`
	Metadata  string `json:"metadata"`
	Sealed    bool   `json:"sealed"`
	// Royalty 是当前版税规则（按收款账户排序）；空表示不收版税。
	// 首次成功发行或封存后固定，不能再设置。
	Royalty []royaltyShare `json:"royalty,omitempty"`
}

// royaltyShare 是版税规则中一个收款账户的份额。
type royaltyShare struct {
	AccountID string `json:"account_id"`
	Rate      int64  `json:"rate"`
}

// royaltyRec 是一笔成功转让的版税应付记录，与持有变化、历史、请求结果
// 在同一临界区内一次落盘。
type royaltyRec struct {
	TxSeq     int64         `json:"tx_seq"`
	ItemID    string        `json:"item_id"`
	SeriesID  string        `json:"series_id"`
	Price     int64         `json:"price"`
	Payees    []payableLine `json:"payees,omitempty"`
	Remainder int64         `json:"remainder"`
	// OwnerID 是转让前持有人，即剩余收入的归属账户（代转时是授权人，
	// 不是受托人）。
	OwnerID string `json:"owner_id"`
}

// payableLine 是一笔转让中某个收款账户的应付明细，零金额也保留。
type payableLine struct {
	AccountID string `json:"account_id"`
	Rate      int64  `json:"rate"`
	Amount    int64  `json:"amount"`
}

// royaltyEvent 是版税规则变更记录：每次成功设置或清空各一条。
type royaltyEvent struct {
	Seq        int64          `json:"seq"`
	SeriesID   string         `json:"series_id"`
	Operator   string         `json:"operator"`
	Reason     string         `json:"reason"`
	RequestID  string         `json:"request_id"`
	Before     []royaltyShare `json:"before,omitempty"`
	After      []royaltyShare `json:"after,omitempty"`
	OccurredAt time.Time      `json:"occurred_at"`
}

type item struct {
	ID         string `json:"id"`
	SeriesID   string `json:"series_id"`
	BatchNo    string `json:"batch_no"`
	Metadata   string `json:"metadata"`
	IssuedTxID int64  `json:"issued_tx_id"`
}

type holding struct {
	ItemID  string `json:"item_id"`
	OwnerID string `json:"owner_id"`
	Version int64  `json:"version"`
}

type historyEntry struct {
	Seq         int64  `json:"seq"`
	Kind        string `json:"kind"`
	ItemID      string `json:"item_id"`
	Operator    string `json:"operator"`
	Reason      string `json:"reason"`
	RequestID   string `json:"request_id"`
	FromID      string `json:"from_id"`
	ToID        string `json:"to_id"`
	FromVersion int64  `json:"from_version"`
	ToVersion   int64  `json:"to_version"`
	// AuthID 非空表示该转让是受托人凭授权完成的代转。
	AuthID string `json:"auth_id,omitempty"`
}

// authzRec 是一份限时一次性代转授权的落盘状态。授权在创建时绑定藏品
// 当时的持有版本（GrantVer）；持有关系后续无论怎样变化，授权都不会
// 恢复或改变。
type authzRec struct {
	ID        string    `json:"id"`
	ItemID    string    `json:"item_id"`
	GranterID string    `json:"granter_id"`
	TrusteeID string    `json:"trustee_id"`
	ToID      string    `json:"to_id"`
	ExpiresAt time.Time `json:"expires_at"`
	GrantVer  int64     `json:"grant_ver"`
	// Price 是创建授权时确定的代转成交价款（分）；旧数据中的授权没有
	// 该字段，按 0 处理。
	Price int64 `json:"price,omitempty"`
	// Status 只记录非时间派生的终态："revoked" 或 "used"；为空表示
	// 尚未终结，当前是否有效由到期时间实时判断。
	Status    string    `json:"status,omitempty"`
	UsedTxSeq int64     `json:"used_tx_seq,omitempty"`
	UsedAt    time.Time `json:"used_at,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	RevokedAt time.Time `json:"revoked_at,omitempty"`
}

// authzEvent 是授权变更记录：创建、撤销、使用各一条。
type authzEvent struct {
	Seq        int64     `json:"seq"`
	AuthID     string    `json:"auth_id"`
	ItemID     string    `json:"item_id"`
	Kind       string    `json:"kind"` // "create" / "revoke" / "use"
	Operator   string    `json:"operator"`
	Reason     string    `json:"reason"`
	RequestID  string    `json:"request_id"`
	FromStatus string    `json:"from_status,omitempty"`
	ToStatus   string    `json:"to_status"`
	TxSeq      int64     `json:"tx_seq,omitempty"`
	OccurredAt time.Time `json:"occurred_at"`
}

// intentRec 是一份藏品拆分意向的落盘状态。意向在创建时绑定藏品当时的
// 持有版本（GrantVer）；持有版本变化或发起人、任一参与账户停用后意向
// 失效，且不因藏品转回原持有人而恢复。
type intentRec struct {
	ID          string        `json:"id"`
	ItemID      string        `json:"item_id"`
	InitiatorID string        `json:"initiator_id"`
	Shares      []intentShare `json:"shares"` // 按账户排序的分配方案
	GrantVer    int64         `json:"grant_ver"`
	ExpiresAt   time.Time     `json:"expires_at"`
	// Status 只记录非时间派生的终态："rejected" 或 "withdrawn"；为空表示
	// 尚未终结，当前是否有效由持有版本、账户状态与到期时间实时判断。
	Status    string    `json:"status,omitempty"`
	CreatedAt time.Time `json:"created_at"`
	EndedAt   time.Time `json:"ended_at,omitempty"`
}

// intentShare 是拆分意向中一个参与账户的份额与答复。
type intentShare struct {
	AccountID string `json:"account_id"`
	Share     int64  `json:"share"`
	// Answer 是该账户的答复："agree" / "reject"；空表示尚未答复。
	// 发起人列入方案时创建即为 "agree"。
	Answer string `json:"answer,omitempty"`
}

// intentEvent 是拆分意向变更记录：创建、首次答复、撤回各一条；重复答复
// 与重复撤回不新增记录。
type intentEvent struct {
	Seq        int64     `json:"seq"`
	IntentID   string    `json:"intent_id"`
	ItemID     string    `json:"item_id"`
	Kind       string    `json:"kind"` // "create" / "answer" / "withdraw"
	Operator   string    `json:"operator"`
	Reason     string    `json:"reason"`
	RequestID  string    `json:"request_id"`
	Answer     string    `json:"answer,omitempty"`
	FromStatus string    `json:"from_status,omitempty"`
	ToStatus   string    `json:"to_status"`
	OccurredAt time.Time `json:"occurred_at"`
}

// request 保存每个 (操作者, 请求号) 的首次结果，用于幂等回放。
// 同一操作者的请求号在发行、转让、授权创建/撤销、代转与版税规则设置
// 之间共用。
type request struct {
	Operator  string `json:"operator"`
	RequestID string `json:"request_id"`
	Kind      string `json:"kind"` // "issue" / "issue_batch" / "transfer" / "transfer_batch" / "auth_create" / "auth_revoke" / "proxy_transfer" / "royalty_set" / "intent_create" / "intent_answer" / "intent_withdraw"
	// 规范化后的业务参数签名。签名一致才回放；不一致报请求号冲突。
	Params string `json:"params"`
	// 业务拒绝也落盘：相同参数重提返回首次的拒绝。
	Rejected bool   `json:"rejected"`
	Reason   string `json:"reject_reason"` // 哨兵错误对应的稳定标识
	// 成功结果。
	ItemID  string `json:"item_id,omitempty"`
	AuthID  string `json:"auth_id,omitempty"`
	FromID  string `json:"from_id,omitempty"`
	ToID    string `json:"to_id,omitempty"`
	Version int64  `json:"version,omitempty"`
	TxSeq   int64  `json:"tx_seq,omitempty"`
	// IntentID 与 Status 记录拆分意向类请求的结果（意向编号与操作后的
	// 意向状态）。
	IntentID string `json:"intent_id,omitempty"`
	Status   string `json:"status,omitempty"`
	// SeriesID 与 Shares 记录版税规则设置的结果（本次生效的规则）。
	SeriesID string         `json:"series_id,omitempty"`
	Shares   []royaltyShare `json:"shares,omitempty"`
	// Batch 记录整批发行各件的首次结果（按提交顺序），仅 kind 为
	// issue_batch 时使用；旧登记册中的请求没有该字段。
	Batch []batchItemResult `json:"batch,omitempty"`
	// TransferBatch 记录整批转让各件的首次结果（按提交顺序），仅 kind
	// 为 transfer_batch 时使用；版税金额回放时从 Royalties 按序号补全。
	TransferBatch []batchTransferItemResult `json:"transfer_batch,omitempty"`
}

// batchItemResult 是整批发行中一件藏品落盘的首次发行结果，用于幂等回放。
type batchItemResult struct {
	ItemID  string `json:"item_id"`
	OwnerID string `json:"owner_id"`
	TxSeq   int64  `json:"tx_seq"`
}

// batchTransferItemResult 是整批转让中一件藏品落盘的首次转让结果，用于
// 幂等回放；价款、应付明细与余款按 TxSeq 从版税应付记录补全。
type batchTransferItemResult struct {
	ItemID  string `json:"item_id"`
	FromID  string `json:"from_id"`
	ToID    string `json:"to_id"`
	Version int64  `json:"version"`
	TxSeq   int64  `json:"tx_seq"`
}

func newSnapshot() *snapshot {
	return &snapshot{
		Version:   stateVersion,
		Accounts:  make(map[string]account),
		Series:    make(map[string]series),
		Items:     make(map[string]item),
		Holdings:  make(map[string]holding),
		Requests:  make(map[string]request),
		Authzs:    make(map[string]authzRec),
		Royalties: make(map[int64]royaltyRec),
		Intents:   make(map[string]intentRec),
	}
}

func (s *snapshot) validate() error {
	if s.Version != stateVersion {
		return fmt.Errorf("%w: 不支持的快照版本 %d", ErrCorrupt, s.Version)
	}
	if s.Accounts == nil || s.Series == nil || s.Items == nil ||
		s.Holdings == nil || s.Requests == nil {
		return fmt.Errorf("%w: 快照内容不完整", ErrCorrupt)
	}
	if s.NextSeq < int64(len(s.History)) {
		return fmt.Errorf("%w: 历史序号不连续", ErrCorrupt)
	}
	if s.Authzs == nil {
		// 兼容旧版本写入的快照：授权表按需惰性建立。
		s.Authzs = make(map[string]authzRec)
	}
	if s.NextAuthSeq < int64(len(s.AuthEvents)) {
		return fmt.Errorf("%w: 授权变更序号不连续", ErrCorrupt)
	}
	if s.Royalties == nil {
		// 兼容旧版本写入的快照：版税应付表按需惰性建立；旧转让没有
		// 应付记录，查询时按价款 0 处理，不补造明细。
		s.Royalties = make(map[int64]royaltyRec)
	}
	if s.NextRoyaltySeq < int64(len(s.RoyaltyEvents)) {
		return fmt.Errorf("%w: 版税规则变更序号不连续", ErrCorrupt)
	}
	if s.Intents == nil {
		// 兼容旧版本写入的快照：拆分意向表按需惰性建立。
		s.Intents = make(map[string]intentRec)
	}
	if s.NextIntentSeq < int64(len(s.IntentEvents)) {
		return fmt.Errorf("%w: 拆分意向变更序号不连续", ErrCorrupt)
	}
	s.rekeyRequests()
	return nil
}

// rekeyRequests 按每条请求记录自身保存的完整操作者账户编号与请求号重建
// 请求表的键。旧版本快照的键由账户编号与请求号直接拼接而成，含零字符
// （U+0000）时不同账户的不同请求会得到相同的键；落盘记录本身始终保存
// 真实的提交账户与请求号，据此重建后旧请求仍归原提交账户所有，使用原
// 参数即可回放原结果，碰巧混淆的另一组编号也不会占用或覆盖原请求。
// 该重建对任意字符组合都是幂等的，每次加载都执行。
func (s *snapshot) rekeyRequests() {
	reqs := make(map[string]request, len(s.Requests))
	for _, req := range s.Requests {
		reqs[requestKey(req.Operator, req.RequestID)] = req
	}
	s.Requests = reqs
}

// store 负责一个登记册目录的加锁、读取与原子写入。
type store struct {
	dir  string
	lock *os.File // 跨进程 flock
}

func dataFile(dir string) string { return filepath.Join(dir, "registry.json") }
func lockFile(dir string) string { return filepath.Join(dir, "registry.lock") }
func tempFile(dir string) string { return filepath.Join(dir, ".registry.json.tmp") }

// acquireLock 在登记册目录中以非阻塞方式取独占 flock。
func acquireLock(dir string) (*os.File, error) {
	f, err := os.OpenFile(lockFile(dir), os.O_CREATE|os.O_RDWR, fileMode)
	if err != nil {
		return nil, fmt.Errorf("registry: 无法打开锁文件: %w", err)
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		f.Close()
		if errors.Is(err, syscall.EWOULDBLOCK) {
			return nil, ErrLocked
		}
		return nil, fmt.Errorf("registry: 无法锁定登记册: %w", err)
	}
	return f, nil
}

// load 读取快照。文件不存在时返回空快照；文件存在但无法读取或解析时
// 返回 ErrCorrupt，绝不静默当成空登记册。
func load(dir string) (*snapshot, error) {
	b, err := os.ReadFile(dataFile(dir))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return newSnapshot(), nil
		}
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if len(b) == 0 {
		return nil, fmt.Errorf("%w: 数据文件为空", ErrCorrupt)
	}
	var s snapshot
	if err := json.Unmarshal(b, &s); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
	}
	if err := s.validate(); err != nil {
		return nil, err
	}
	return &s, nil
}

// save 以 temp 文件 + fsync + rename + 目录 fsync 的方式原子替换快照。
// 在持有全局锁时调用：写入与状态修改在同一临界区，进程被杀时要么
// 完整保留旧状态，要么完整呈现新状态。
func (st *store) save(s *snapshot) error {
	b, err := json.MarshalIndent(s, "", "  ")
	if err != nil {
		return fmt.Errorf("registry: 序列化失败: %w", err)
	}
	tmp := tempFile(st.dir)
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, fileMode)
	if err != nil {
		return fmt.Errorf("registry: 无法写入登记册: %w", err)
	}
	ok := false
	defer func() {
		if !ok {
			f.Close()
			os.Remove(tmp)
		}
	}()
	if _, err := f.Write(b); err != nil {
		return fmt.Errorf("registry: 写入失败: %w", err)
	}
	if err := f.Sync(); err != nil {
		return fmt.Errorf("registry: 落盘失败: %w", err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("registry: 关闭临时文件失败: %w", err)
	}
	if err := os.Rename(tmp, dataFile(st.dir)); err != nil {
		return fmt.Errorf("registry: 替换数据文件失败: %w", err)
	}
	if dirFd, err := os.Open(st.dir); err == nil {
		_ = dirFd.Sync()
		dirFd.Close()
	}
	ok = true
	return nil
}

