810	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
811		if prev.Kind != "auth_create" || prev.Params != sig {
812			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
813				ErrRequestConflict, prev.Operator, prev.RequestID)
814		}
815		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
816			Status: AuthActive, Replayed: true}
817		if prev.Rejected {
818			res.Err = codeErr(prev.Reason)
819			return res, res.Err
820		}
821		return res, nil
822	}
823	
824	func revokeAuthzParamsSig(req RevokeAuthorizationRequest) string {
825		b, _ := json.Marshal(struct {
826			Kind   string `json:"kind"`
827			AuthID string `json:"auth_id"`
828			Reason string `json:"reason"`
829		}{"auth_revoke", req.AuthID, req.Reason})
830		return string(b)
831	}
832	
833	// RevokeAuthorization 撤销一份尚未使用的代转授权。仅授权人可以撤销；
834	// 已使用的授权不能撤销（返回 ErrAuthorizationUsed）。授权已撤销时再次
835	// 撤销不新增授权变更记录，按成功返回。请求号语义与其他操作一致。
836	func (r *Registry) RevokeAuthorization(req RevokeAuthorizationRequest) (RevokeAuthorizationResult, error) {
837		missing := []string{}
838		if strings.TrimSpace(req.Operator) == "" {
839			missing = append(missing, "operator")
840		}
841		if strings.TrimSpace(req.Reason) == "" {
842			missing = append(missing, "reason")
843		}
844		if strings.TrimSpace(req.RequestID) == "" {
845			missing = append(missing, "request_id")
846		}
847		if strings.TrimSpace(req.AuthID) == "" {
848			missing = append(missing, "auth_id")
849		}
850		if len(missing) > 0 {
851			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 撤销授权请求缺少必填字段 %s",
852				ErrInvalidArgument, strings.Join(missing, ", "))
853		}
854		r.mu.Lock()
855		defer r.mu.Unlock()
856		if err := r.checkOpen(); err != nil {
857			return RevokeAuthorizationResult{}, err
858		}
859	
860		now := r.now()
861		key := requestKey(req.Operator, req.RequestID)
862		sig := revokeAuthzParamsSig(req)
863		if prev, ok := r.state.Requests[key]; ok {
864			return r.replayRevokeAuthz(prev, sig)
865		}
866	
867		a, ok := r.state.Authzs[req.AuthID]
868		if !ok {
869			// 引用不存在不占用请求号。
870			err := fmt.Errorf("%w: 授权 %s", ErrNotFound, req.AuthID)
871			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: err}, err
872		}
873		if a.GranterID != req.Operator {
874			bizErr := fmt.Errorf("%w: 只有授权人 %s 可以撤销授权 %s",
875				ErrForbidden, a.GranterID, req.AuthID)
876			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
877			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
878		}
879		switch authzCurrentStatus(a, now) {
880		case AuthUsed:
881			bizErr := fmt.Errorf("%w: 授权 %s 已使用，不能撤销", ErrAuthorizationUsed, req.AuthID)
882			r.recordAuthzRequest(key, sig, req, "auth_revoke", bizErr)
883			return RevokeAuthorizationResult{AuthID: req.AuthID, Err: bizErr}, bizErr
884		case AuthRevoked:
885			// 已撤销是幂等终态：不新增授权变更记录；该请求号仍登记为成功，
886			// 相同请求重放回放同一结果。
887			r.state.Requests[key] = request{
888				Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
889				Params: sig, AuthID: req.AuthID,
890			}
891			if err := r.commit(); err != nil {
892				return RevokeAuthorizationResult{}, err
893			}
894			return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
895		}
896	
897		from := AuthActive
898		if authzCurrentStatus(a, now) == AuthExpired {
899			from = AuthExpired
900		}
901		a.Status = "revoked"
902		a.RevokedAt = now
903		r.state.Authzs[req.AuthID] = a
904		authSeq := r.state.NextAuthSeq + 1
905		r.state.NextAuthSeq = authSeq
906		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
907			Seq: authSeq, AuthID: req.AuthID, ItemID: a.ItemID, Kind: "revoke",
908			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
909			FromStatus: from, ToStatus: AuthRevoked, OccurredAt: now,
910		})
911		r.state.Requests[key] = request{
912			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
913			Params: sig, AuthID: req.AuthID,
914		}
915		if err := r.commit(); err != nil {
916			return RevokeAuthorizationResult{}, err
917		}
918		return RevokeAuthorizationResult{AuthID: req.AuthID, Status: AuthRevoked}, nil
919	}
920	
921	// recordAuthzRequest 记录授权类操作的状态类业务拒绝并尽力落盘。
922	func (r *Registry) recordAuthzRequest(key, sig string, req RevokeAuthorizationRequest, kind string, bizErr error) {
923		r.state.Requests[key] = request{
924			Operator: req.Operator, RequestID: req.RequestID, Kind: kind,
925			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
926		}
927		_ = r.commit()
928	}
929	
930	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
931		if prev.Kind != "auth_revoke" || prev.Params != sig {
932			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
933				ErrRequestConflict, prev.Operator, prev.RequestID)
934		}
935		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
936		if prev.Rejected {
937			res.Err = codeErr(prev.Reason)
938			res.Status = ""
939			return res, res.Err
940		}
941		return res, nil
942	}
