package registry

import (
	"errors"
	"os"
	"testing"
)

// 临时验证：拒绝结果保存失败 → 返回保存错误、空结果、不占请求号。
func TestTmpRoyaltyRejectSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)
	if err := r.SealSeries("s1", "alice"); err != nil {
		t.Fatal(err)
	}
	req := SetRoyaltyRequest{
		Operator: "alice", Reason: "设置", RequestID: "rq1",
		SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "bob", Rate: 500}},
	}
	blockBatchSave(t, r)
	res, err := r.SetRoyalty(req)
	assertSaveFailureError(t, err)
	if res.SeriesID != "" || res.Shares != nil || res.Err != nil || res.Replayed {
		t.Fatalf("结果应为空: %+v", res)
	}
	if _, ok := r.state.Requests[requestKey("alice", "rq1")]; ok {
		t.Fatal("未保存的拒绝不应占用请求号")
	}
	restoreBatchSave(t, r)
	res, err = r.SetRoyalty(req)
	if !errors.Is(err, ErrSeriesSealed) || res.Replayed || res.SeriesID != "s1" {
		t.Fatalf("重提应重新判断并保存拒绝: %+v, %v", res, err)
	}
	res, err = r.SetRoyalty(req)
	if !errors.Is(err, ErrSeriesSealed) || !res.Replayed {
		t.Fatalf("再次提交应回放: %+v, %v", res, err)
	}
}

// 临时验证：成功保存失败且磁盘不可读 → 显式回滚，规则/变更/序号/请求号全部复原。
func TestTmpRoyaltySuccessSaveFailureUnreadable(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)
	// 先设置一条已有规则，之后替换它时保存失败，原规则须完整保留。
	first := SetRoyaltyRequest{
		Operator: "alice", Reason: "首次", RequestID: "rq0",
		SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "alice", Rate: 300}},
	}
	if _, err := r.SetRoyalty(first); err != nil {
		t.Fatal(err)
	}
	req := SetRoyaltyRequest{
		Operator: "alice", Reason: "替换", RequestID: "rq1",
		SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "bob", Rate: 500}},
	}
	orig, err := os.ReadFile(dataFile(r.dir))
	if err != nil {
		t.Fatal(err)
	}
	blockBatchSave(t, r)
	if err := os.WriteFile(dataFile(r.dir), []byte("{corrupt"), fileMode); err != nil {
		t.Fatal(err)
	}
	res, err := r.SetRoyalty(req)
	assertSaveFailureError(t, err)
	if res.SeriesID != "" || res.Shares != nil || res.Err != nil || res.Replayed {
		t.Fatalf("结果应为空: %+v", res)
	}
	// 状态未能重建时也必须显式撤销。
	cur, err := r.GetSeriesRoyalty("s1")
	if err != nil || len(cur) != 1 || cur[0].AccountID != "alice" || cur[0].Rate != 300 {
		t.Fatalf("原规则应完整保留: %+v, %v", cur, err)
	}
	evs, err := r.RoyaltyHistory("s1")
	if err != nil || len(evs) != 1 {
		t.Fatalf("变更记录应保持 1 条: %+v, %v", evs, err)
	}
	if r.state.NextRoyaltySeq != 1 {
		t.Fatalf("NextRoyaltySeq = %d, want 1", r.state.NextRoyaltySeq)
	}
	if _, ok := r.state.Requests[requestKey("alice", "rq1")]; ok {
		t.Fatal("未保存的设置不应占用请求号")
	}
	// 恢复读写；其他操作成功保存不得夹带未保存内容。
	if err := os.WriteFile(dataFile(r.dir), orig, fileMode); err != nil {
		t.Fatal(err)
	}
	restoreBatchSave(t, r)
	if err := r.RegisterAccount("carol", ""); err != nil {
		t.Fatal(err)
	}
	cur, _ = r.GetSeriesRoyalty("s1")
	if len(cur) != 1 || cur[0].AccountID != "alice" {
		t.Fatalf("后续保存不应夹带未保存规则: %+v", cur)
	}
	if _, ok := r.state.Requests[requestKey("alice", "rq1")]; ok {
		t.Fatal("后续保存不应夹带未保存的请求记录")
	}
	// 原请求重提：正常设置，不标回放。
	res, err = r.SetRoyalty(req)
	if err != nil || res.Replayed || res.SeriesID != "s1" || len(res.Shares) != 1 || res.Shares[0].AccountID != "bob" {
		t.Fatalf("重提应正常设置: %+v, %v", res, err)
	}
	if r.state.NextRoyaltySeq != 2 {
		t.Fatalf("NextRoyaltySeq = %d, want 2", r.state.NextRoyaltySeq)
	}
	res, err = r.SetRoyalty(req)
	if err != nil || !res.Replayed {
		t.Fatalf("成功后重提应回放: %+v, %v", res, err)
	}
}

// 临时验证：清空规则保存失败（磁盘可读，状态可重建）→ 原规则保留。
func TestTmpRoyaltyClearSaveFailure(t *testing.T) {
	r := mustCreate(t, tempDir(t))
	setupWorld(t, r)
	first := SetRoyaltyRequest{
		Operator: "alice", Reason: "首次", RequestID: "rq0",
		SeriesID: "s1", Shares: []RoyaltyShare{{AccountID: "alice", Rate: 300}},
	}
	if _, err := r.SetRoyalty(first); err != nil {
		t.Fatal(err)
	}
	clear := SetRoyaltyRequest{Operator: "alice", Reason: "清空", RequestID: "rq1", SeriesID: "s1"}
	blockBatchSave(t, r)
	res, err := r.SetRoyalty(clear)
	assertSaveFailureError(t, err)
	if res.SeriesID != "" || res.Shares != nil {
		t.Fatalf("结果应为空: %+v", res)
	}
	cur, _ := r.GetSeriesRoyalty("s1")
	if len(cur) != 1 || cur[0].Rate != 300 {
		t.Fatalf("清空失败应保留原规则: %+v", cur)
	}
	restoreBatchSave(t, r)
	res, err = r.SetRoyalty(clear)
	if err != nil || res.Replayed || len(res.Shares) != 0 {
		t.Fatalf("重提应正常清空: %+v, %v", res, err)
	}
	cur, _ = r.GetSeriesRoyalty("s1")
	if len(cur) != 0 {
		t.Fatalf("清空后应为空规则: %+v", cur)
	}
}

